@router.get({{path}}, response_model=list[ChildRead])
async def list_child(parent_id: int, {{filter_field}}: bool | None = None, before: date | None = None, page_size: Annotated[int, Query(alias="limit", ge=1, le={{max_limit}})] = 20, offset: Annotated[int, Query(ge=0)] = 0) -> list[Child]:
    """List child."""
    filters: dict[str, object] = {"{{foreign_key}}": parent_id}
    await require_parent(parent_id)
    if {{filter_field}} is not None:
        filters["{{filter_field}}"] = {{filter_field}}
    if before is not None:
        filters["{{date_field}}"] = {"$lt": datetime.combine(before, time(), UTC), "$ne": None}
    return await Child.find(filters).sort("_id").skip(offset).limit(page_size).to_list()
